#include "../common.h"
int main(void){char bits[100];int key=0x1FD,counter=0,ct[100],n=0;printf("Enter plaintext bytes as hex: ");scanf("%99s",bits);printf("Ciphertext: ");for(int i=0;bits[2*i]&&bits[2*i+1];i++,counter++){unsigned x=0;sscanf(bits+2*i,"%2x",&x);ct[n++]=(int)x^sdes8(counter&255,key,0);printf("%02X",ct[n-1]);}puts("");printf("Decrypted: ");for(int i=0;i<n;i++)printf("%02X",ct[i]^sdes8(i&255,key,0));puts("");puts("CTR encryption and decryption both XOR with the same counter keystream.");return 0;}